import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, mix, float, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-cta';
  group.position.set(0, -2.85, 0.26);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.7;
  const height = 1.06;

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.RepeatWrapping;
  map.wrapT = THREE.RepeatWrapping;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial();

  const baseTex = texture(map, uv());

  const ink = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const accent = vec3(0xff / 255, 0x2a / 255, 0x38 / 255);

  // engineered gradient: vertical mix between ink and accent tint, modulated by brushed metal map
  const gradientMix = uv().y.clamp(0.0, 1.0);
  const gradient = mix(ink, mix(ink, accent, float(0.18)), gradientMix);

  const grainStrength = uniform(0.035);
  const combined = gradient.mul(baseTex.rgb).add(baseTex.rgb.mul(grainStrength));

  material.colorNode = vec3(combined.r, combined.g, combined.b);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'home-cta-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'Get started',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    atlas: ctx.fontAtlas,
    anchor: 'center',
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
  };

  return group;
}
